import {
  Button,
  DateInput,
  DatePicker as AriaDatePicker,
  DateSegment,
  Dialog,
  FieldError,
  Group,
  Label,
  Popover,
  Text,
  type DatePickerProps as AriaDatePickerProps,
  type DateValue,
} from "react-aria-components";
import { Calendar } from "../calendar/calendar";
import { datePickerDefaults, type DatePickerSpecProps } from "../generated/date-picker.types";
import { cx } from "../utils/cx";
import {
  fieldError,
  fieldGroup,
  fieldGroupSizes,
  fieldHelp,
  fieldLabel,
  iconButton,
  overlayPanel,
  segment,
} from "../utils/field";
import { CalendarIcon } from "../utils/icons";

// Generic like React Aria's, so value and onChange keep your date type:
// useState<CalendarDate | null> works without casts.
export interface DatePickerProps<T extends DateValue = DateValue>
  extends Omit<DatePickerSpecProps, "value" | "defaultValue" | "onChange">,
    Omit<AriaDatePickerProps<T>, Exclude<keyof DatePickerSpecProps, "value" | "defaultValue" | "onChange"> | "className" | "children"> {
  className?: string;
}

export function DatePicker<T extends DateValue = DateValue>({
  label,
  description,
  errorMessage,
  size = datePickerDefaults.size,
  granularity = datePickerDefaults.granularity,
  isDisabled = datePickerDefaults.isDisabled,
  // Left undefined unless passed: React Aria treats any defined isInvalid as
  // controlled and would hide its own validation (required, min/max...).
  isInvalid,
  isRequired = datePickerDefaults.isRequired,
  className,
  ...rest
}: DatePickerProps<T>) {
  return (
    <AriaDatePicker
      {...rest}
      granularity={granularity}
      isDisabled={isDisabled}
      isInvalid={isInvalid}
      isRequired={isRequired}
      className={cx("group flex flex-col gap-1.5", className)}
    >
      <Label className={fieldLabel}>
        {label}
        {isRequired && <span aria-hidden="true" className="text-[var(--rd-color-feedback-danger)]"> *</span>}
      </Label>
      <Group className={cx(fieldGroup, fieldGroupSizes[size])}>
        <DateInput className="flex flex-1">{(seg) => <DateSegment segment={seg} className={segment} />}</DateInput>
        <Button className={iconButton}>
          <CalendarIcon />
        </Button>
      </Group>
      {description && (
        <Text slot="description" className={fieldHelp}>
          {description}
        </Text>
      )}
      <FieldError className={fieldError}>{errorMessage}</FieldError>
      <Popover className={cx(overlayPanel, "overflow-auto")}>
        <Dialog className="p-3 outline-none">
          <Calendar />
        </Dialog>
      </Popover>
    </AriaDatePicker>
  );
}

// Generated by rdloom codegen from specs/date-picker.spec.json (v0.1.1).
// Do not edit. Change the spec and run `npm run gen`.

export const datePickerSizeValues = ["sm", "md", "lg"] as const;
export const datePickerGranularityValues = ["day", "hour", "minute"] as const;

/** Date field with a calendar popover. Typing and picking both work, in the user's locale. */
export interface DatePickerSpecProps {
  /**
   * Visible label.
   */
  label: string;
  /**
   * Help text under the field.
   */
  description?: string;
  /**
   * Shown when the field is invalid.
   */
  errorMessage?: string;
  /**
   * Field height and font size.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Smallest editable unit. hour/minute add time segments.
   * @default "day"
   */
  granularity?: "day" | "hour" | "minute";
  /**
   * Controlled value.
   */
  value?: import("react-aria-components").DateValue | null;
  /**
   * Initial value when uncontrolled.
   */
  defaultValue?: import("react-aria-components").DateValue;
  /**
   * Earliest allowed date.
   */
  minValue?: import("react-aria-components").DateValue;
  /**
   * Latest allowed date.
   */
  maxValue?: import("react-aria-components").DateValue;
  /**
   * Prevents editing and dims the field.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Marks the value invalid and shows errorMessage.
   * @default false
   */
  isInvalid?: boolean;
  /**
   * Requires a date for form submission.
   * @default false
   */
  isRequired?: boolean;
  /**
   * Called when the date changes.
   */
  onChange?: (value: import("react-aria-components").DateValue | null) => void;
}

export const datePickerDefaults = {
  size: "md",
  granularity: "day",
  isDisabled: false,
  isInvalid: false,
  isRequired: false,
} as const;

export const datePickerMeta = {
  "name": "DatePicker",
  "version": "0.1.1",
  "status": "experimental",
  "role": "group"
} as const;
